/**
 * Original artwork and media for the v0.2 example projects. The video and GIF
 * are generated by scripts/make-example-media.py (no third-party footage).
 */
import type { Asset } from '../model/types';
import { fnv, svgAsset } from './art';
import walkthroughUrl from './media/walkthrough.webm?inline';
import confettiUrl from './media/confetti.gif?inline';

const bytesOf = (dataUrl: string) =>
  Math.floor(((dataUrl.length - dataUrl.indexOf(',') - 1) * 3) / 4) - (dataUrl.endsWith('==') ? 2 : dataUrl.endsWith('=') ? 1 : 0);

function dataAsset(id: string, name: string, data: string, width: number, height: number, extra: Partial<Asset> = {}): Asset {
  const mime = data.slice(5, data.indexOf(';'));
  return { id, name, mime, data, width, height, bytes: bytesOf(data), hash: fnv(data), ...extra };
}

export const walkthroughVideo = () => dataAsset('as_walkthrough', 'tasklane-walkthrough.webm', walkthroughUrl, 640, 360, { duration: 7 });
export const confettiGif = () => dataAsset('as_confetti', 'confetti.gif', confettiUrl, 220, 220, { animated: true });

const wrap = (w: number, h: number, body: string) => `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}">${body}</svg>`;

/** Dashboard mock-up of the fictional "Tasklane" app (Professional example). */
export function dashboardArt(): Asset {
  const bars = [46, 62, 54, 78, 70, 92, 84]
    .map((v, i) => `<rect x="${352 + i * 34}" y="${296 - v * 1.6}" width="20" height="${v * 1.6}" rx="4" fill="${i === 5 ? '#2563eb' : '#bfd3fb'}"/>`)
    .join('');
  const body = `
  <rect width="800" height="520" rx="22" fill="#ffffff"/>
  <rect width="800" height="44" rx="22" fill="#f1f5f9"/><rect y="22" width="800" height="22" fill="#f1f5f9"/>
  <circle cx="26" cy="22" r="6" fill="#ff5f57"/><circle cx="46" cy="22" r="6" fill="#febc2e"/><circle cx="66" cy="22" r="6" fill="#28c840"/>
  <rect x="300" y="14" width="200" height="16" rx="8" fill="#e2e8f0"/>
  <rect x="0" y="44" width="180" height="476" fill="#f8fafc"/>
  <rect x="22" y="70" width="28" height="28" rx="8" fill="#2563eb"/><rect x="60" y="78" width="80" height="12" rx="6" fill="#0f172a"/>
  ${[0, 1, 2, 3, 4].map((i) => `<rect x="22" y="${130 + i * 38}" width="${i === 0 ? 136 : 100}" height="${i === 0 ? 28 : 10}" rx="${i === 0 ? 8 : 5}" fill="${i === 0 ? '#e8effd' : '#cbd5e1'}" ${i === 0 ? '' : `transform="translate(14 9)"`}/>`).join('')}
  <rect x="210" y="72" width="220" height="18" rx="9" fill="#0f172a"/>
  <rect x="210" y="100" width="150" height="10" rx="5" fill="#94a3b8"/>
  ${[0, 1, 2].map((i) => `<rect x="${210 + i * 190}" y="134" width="172" height="86" rx="14" fill="#ffffff" stroke="#e2e8f0" stroke-width="2"/><rect x="${228 + i * 190}" y="154" width="70" height="10" rx="5" fill="#94a3b8"/><rect x="${228 + i * 190}" y="178" width="${[96, 74, 110][i]}" height="22" rx="6" fill="${['#0f172a', '#2563eb', '#0ea5e9'][i]}"/>`).join('')}
  <rect x="210" y="240" width="120" height="250" rx="14" fill="#ffffff" stroke="#e2e8f0" stroke-width="2"/>
  ${[0, 1, 2, 3, 4].map((i) => `<rect x="226" y="${262 + i * 44}" width="88" height="30" rx="8" fill="${i === 1 ? '#e8effd' : '#f1f5f9'}"/>`).join('')}
  <rect x="340" y="240" width="440" height="250" rx="14" fill="#ffffff" stroke="#e2e8f0" stroke-width="2"/>
  <rect x="352" y="256" width="120" height="10" rx="5" fill="#0f172a"/>
  ${bars.replace(/y="(\d+(\.\d+)?)"/g, (_, y) => `y="${Number(y) + 170}"`)}
  <path d="M352 466 H760" stroke="#e2e8f0" stroke-width="2"/>`;
  return svgAsset('as_dashboard', 'Tasklane dashboard', wrap(800, 520, body), 800, 520);
}

/** A rooftop terrace at dusk with string lights (Editorial example). */
export function rooftopArt(): Asset {
  const lights = Array.from({ length: 15 }, (_, i) => {
    const x = 40 + i * 52;
    const y = 120 + Math.sin((i / 14) * Math.PI) * 46;
    return `<circle cx="${x}" cy="${y.toFixed(1)}" r="7" fill="#ffd89a"/><circle cx="${x}" cy="${y.toFixed(1)}" r="16" fill="#ffd89a" opacity=".22"/>`;
  }).join('');
  const towers = [
    [30, 300, 80],
    [120, 250, 60],
    [190, 330, 90],
    [290, 280, 70],
    [370, 220, 54],
    [430, 310, 100],
    [540, 260, 66],
    [610, 330, 84],
    [700, 240, 70],
  ]
    .map(
      ([x, y, w]) =>
        `<rect x="${x}" y="${y}" width="${w}" height="${560 - y}" fill="#5c3b31"/>` +
        Array.from(
          { length: 6 },
          (_, k) =>
            `<rect x="${x + 12 + (k % 2) * (w / 2 - 6)}" y="${y + 20 + Math.floor(k / 2) * 34}" width="10" height="14" fill="#f2c38b" opacity="${k % 3 ? 0.85 : 0.35}"/>`,
        ).join(''),
    )
    .join('');
  const body = `
  <defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b2a24"/><stop offset=".55" stop-color="#b5532c"/><stop offset="1" stop-color="#f2c38b"/></linearGradient></defs>
  <rect width="800" height="560" fill="url(#sky)"/>
  <circle cx="610" cy="300" r="70" fill="#f8d9a8" opacity=".9"/>
  ${towers}
  <path d="M0 130 Q400 220 800 130" stroke="#2b2320" stroke-width="2" fill="none" opacity=".7"/>
  ${lights}
  <rect y="430" width="800" height="130" fill="#2b2320"/>
  <rect y="424" width="800" height="10" fill="#6b4a3c"/>
  ${[120, 360, 600].map((x) => `<ellipse cx="${x}" cy="500" rx="70" ry="14" fill="#4a3530"/><rect x="${x - 6}" y="470" width="12" height="30" fill="#4a3530"/><ellipse cx="${x}" cy="470" rx="54" ry="10" fill="#7a5547"/>`).join('')}
  ${[150, 330, 380, 630].map((x, i) => `<rect x="${x}" y="448" width="12" height="22" rx="3" fill="${['#d99a3d', '#6f8f5c', '#c0645a', '#d99a3d'][i]}"/>`).join('')}`;
  return svgAsset('as_rooftop', 'Rooftop terrace at dusk', wrap(800, 560, body), 800, 560);
}

/** Small icon tiles for the Editorial details cards. */
export function iconArt(kind: 'calendar' | 'pin' | 'cake'): Asset {
  const icons: Record<string, string> = {
    calendar: `<rect x="22" y="30" width="76" height="68" rx="12" fill="#fffdf9" stroke="#b5532c" stroke-width="6"/><path d="M22 52h76" stroke="#b5532c" stroke-width="6"/><path d="M42 22v16M78 22v16" stroke="#b5532c" stroke-width="6" stroke-linecap="round"/><circle cx="60" cy="74" r="9" fill="#d99a3d"/>`,
    pin: `<path d="M60 104s-32-30-32-56a32 32 0 0 1 64 0c0 26-32 56-32 56z" fill="#fffdf9" stroke="#b5532c" stroke-width="6"/><circle cx="60" cy="48" r="11" fill="#d99a3d"/>`,
    cake: `<rect x="24" y="58" width="72" height="40" rx="8" fill="#fffdf9" stroke="#b5532c" stroke-width="6"/><path d="M24 74c12 8 24-8 36 0s24 8 36 0" stroke="#d99a3d" stroke-width="5" fill="none"/><path d="M60 58V40" stroke="#b5532c" stroke-width="6" stroke-linecap="round"/><path d="M60 22c6 6 6 12 0 14-6-2-6-8 0-14z" fill="#d99a3d"/>`,
  };
  return svgAsset(`as_icon_${kind}`, `${kind} icon`, wrap(120, 120, `<circle cx="60" cy="60" r="60" fill="#f6e3d6"/>${icons[kind]}`), 120, 120);
}
